heorem placedAAMeasurement_effect {P : AdmissibleParams} {ε : ℝ} +    (S : ProjectiveSetting P ε) {α : Type*} [Fintype α] +    (M : Measurement α (S.ExpandedLocalSpace .alice)) (a : α) : +    (placedAAMeasurement S M).effect a = S.place .AA' (M.effect a) := by +  change reindexOp +    (ProjectiveSetting.aaBaBipartition P S.toStrategy.ιA S.toStrategy.ιB) +      (heteroKron (M.effect a) 1) = S.place .AA' (M.effect a) +  exact ProjectiveSetting.reindexOp_aaBaBipartition_left S (M.effect a) + +/-- A product-distribution average is the corresponding iterated average. -/ +private theorem avgOver_prod_current {α β : Type*} +    [DecidableEq α] [DecidableEq β] +    (μ : Distribution α) (ν : Distribution β) (f : α × β → ℝ) : +    avgOver (Distribution.prod μ ν) f = +      avgOver μ (fun a => avgOver ν (fun b => f (a, b))) := by +  classical +  unfold avgOver +  change (∑ p ∈ μ.support ×ˢ ν.support, +    μ.weight p.1 * ν.weight p.2 * f p) = _ +  rw [Finset.sum_product] +  refine Finset.sum_congr rfl fun a _ => ?_ +  rw [Finset.mul_sum] +  exact Finset.sum_congr rfl fun b _ => by ring + +/-- The completed point measurement has zero effect at `none`. -/ +private theorem pointMeasExpOption_effect_none_current +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) +    (side : PlayerSide) (W : PauliKind) (u : Fin P.m → PauliScalar P) : +    (S.pointMeasExpOption side W u).effect none = 0 := by +  classical +  unfold ProjectiveSetting.pointMeasExpOption +  rw [MIPStarRE.Quantum.Measurement.postprocess_effect] +  apply Finset.sum_eq_zero +  intro a ha +  exact absurd (Finset.mem_filter.mp ha).2 (by simp) + +/-- The completed point measurement agrees with the original measurement at +a `some` outcome. -/ +private theorem pointMeasExpOption_effect_some_current +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) +    (side : PlayerSide) (W : PauliKind) (u : Fin P.m → PauliScalar P) +    (a : PauliScalar P) : +    (S.pointMeasExpOption side W u).effect (some a) = +      (S.pointMeasExp side W u).effect a := by +  classical +  unfold ProjectiveSetting.pointMeasExpOption +  rw [MIPStarRE.Quantum.Measurement.postprocess_effect] +  simp [Finset.filter_eq'] + +/-- Evaluating a completed point effect through a line answer gives the +explicit zero-completed effect used in the claim statements. -/ +private theorem pointMeasExpOption_effect_evalOpt_current +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) +    (side : PlayerSide) (W : PauliKind) (line : LineDesc P.toLdParams) +    (u : Fin P.m → PauliScalar P) +    (f : DegPoly P.toLdParams (P.m * P.d)) : +    (S.pointMeasExpOption side W u).effect (evalOpt line u f) = +      S.expPointEffectAtLineAnswer side W line u f := by +  unfold ProjectiveSetting.expPointEffectAtLineAnswer +  cases evalOpt line u f with +  | none => exact pointMeasExpOption_effect_none_current S side W u +  | some a => exact pointMeasExpOption_effect_some_current S side W u a + +private theorem rpow_quarter_nonneg (x : ℝ) : 0 ≤ Real.rpow x (1 / 4 : ℝ) := by +  change 0 ≤ x ^ (1 / 4 : ℝ) +  rcases lt_or_ge x 0 with hx | hx +  · rw [Real.rpow_def_of_neg hx, +      show (1 / 4 : ℝ) * Real.pi = Real.pi / 4 by ring, Real.cos_pi_div_four] +    positivity +  · exact Real.rpow_nonneg hx _ + +private theorem sqrt_deficit_bound_le (m δP δQ : ℝ) (hm : 1 ≤ m) (hP : 0 ≤ δP) +    (hQ : 0 ≤ δQ) : +    Real.sqrt (2 * Real.sqrt (4 * m ^ 2 * δP) + 2 * Real.sqrt (4 * δQ)) ≤ +      2 * Real.sqrt m * (Real.rpow δP (1 / 4 : ℝ) + Real.rpow δQ (1 / 4 : ℝ)) := by +  have hm0 : 0 ≤ m := by linarith +  have hsqrtm : 1 ≤ Real.sqrt m := by +    rw [← Real.sqrt_one] +    exact Real.sqrt_le_sqrt hm +  have h1 : Real.sqrt (4 * m ^ 2 * δP) = 2 * m * Real.sqrt δP := by +    rw [Real.sqrt_mul (by positivity), show (4 * m ^ 2 : ℝ) = (2 * m) ^ 2 by ring, +      Real.sqrt_sq (by linarith)] +  have h2 : Real.sqrt (4 * δQ) = 2 * Real.sqrt δQ := by +    rw [Real.sqrt_mul (by norm_num), show (4 : ℝ) = 2 ^ 2 by norm_num, +      Real.sqrt_sq (by norm_num)] +  have hquarter : ∀ x : ℝ, 0 ≤ x → +      Real.sqrt (Real.sqrt x) = Real.rpow x (1 / 4 : ℝ) := by +    intro x hx +    rw [Real.sqrt_eq_rpow, Real.sqrt_eq_rpow, ← Real.rpow_mul hx] +    norm_num +  have hsplit : ∀ a b : ℝ, 0 ≤ a → 0 ≤ b → +      Real.sqrt (a + b) ≤ Real.sqrt a + Real.sqrt b := by +    intro a b ha hb +    rw [← Real.sqrt_sq (add_nonneg (Real.sqrt_nonneg a) (Real.sqrt_nonneg b))] +    refine Real.sqrt_le_sqrt ?_ +    nlinarith [Real.sq_sqrt ha, Real.sq_sqrt hb, Real.sqrt_nonneg a, +      Real.sqrt_nonneg b] +  have hPa : 0 ≤ 2 * (2 * m * Real.sqrt δP) := +    mul_nonneg (by norm_num) +      (mul_nonneg (mul_nonneg (by norm_num) hm0) (Real.sqrt_nonneg _)) +  have hQa : 0 ≤ 2 * (2 * Real.sqrt δQ) := +    mul_nonneg (by norm_num) (mul_nonneg (by norm_num) (Real.sqrt_nonneg _)) +  have hPb : Real.sqrt (2 * (2 * m * Real.sqrt δP)) = +      2 * Real.sqrt m * Real.rpow δP (1 / 4 : ℝ) := by +    rw [show 2 * (2 * m * Real.sqrt δP) = 2 ^ 2 * m * Real.sqrt δP by ring, +      Real.sqrt_mul (by positivity), Real.sqrt_mul (by positivity : (0 : ℝ) ≤ 2 ^ 2), +      Real.sqrt_sq (by norm_num : (0 : ℝ) ≤ 2), hquarter δP hP] +  have hQb : Real.sqrt (2 * (2 * Real.sqrt δQ)) = 2 * Real.rpow δQ (1 / 4 : ℝ) := by +    rw [show 2 * (2 * Real.sqrt δQ) = 2 ^ 2 * Real.sqrt δQ by ring, +      Real.sqrt_mul (by positivity : (0 : ℝ) ≤ 2 ^ 2), +      Real.sqrt_sq (by norm_num : (0 : ℝ) ≤ 2), hquarter δQ hQ] +  rw [h1, h2] +  calc +    Real.sqrt (2 * (2 * m * Real.sqrt δP) + 2 * (2 * Real.sqrt δQ)) +        ≤ Real.sqrt (2 * (2 * m * Real.sqrt δP)) + +          Real.sqrt (2 * (2 * Real.sqrt δQ)) := hsplit _ _ hPa hQa +    _ = 2 * Real.sqrt m * Real.rpow δP (1 / 4 : ℝ) + +          2 * Real.rpow δQ (1 / 4 : ℝ) := by rw [hPb, hQb] +    _ ≤ 2 * Real.sqrt m * +          (Real.rpow δP (1 / 4 : ℝ) + Real.rpow δQ (1 / 4 : ℝ)) := by +      have hQ4 : 0 ≤ Real.rpow δQ (1 / 4 : ℝ) := Real.rpow_nonneg hQ _ +      nlinarith [hsqrtm, hQ4] + +/-- Regroup paired-line answers by 