efect at hbound ⊢ +  refine le_trans +    (avgOver_prod_restrictedLinePointDist_le _ ?_ kindX kindZ i j) ?_ +  · intro sample +    exact consistencyDefect_integrand_nonneg S p₁ p₂ hopp (M₁ sample) +      (M₂ sample) +  · exact mul_le_mul_of_nonneg_left hbound (by positivity)    /-- The evaluated joint line measurement remains consistent with the joint  point measurement on every product of restricted line distributions. @@ -158,10 +270,8 @@ blueprint  `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1058-1061`.  Here `consistencyDefect` is the finite POVM form of the displayed expectation  against `Id - Q` after both measurements are postprocessed by evaluation. -The universal constant is outside all strategy and parameter quantifiers.  The -proof is tracked by issue #18.  Discharge: apply -`avg_restricted_prod_le` to `CombinedLinesWitness.consistent` and unfold -`consistencyDefect`. -/ +The universal constant is outside all strategy and parameter quantifiers, and +is the exact inflation factor `4` of `avg_restricted_prod_le`. -/  theorem restricted_lines_consistency_bound :      ∃ C : ℝ, 0 < C ∧        ∀ {P : AdmissibleParams} {ε δQ δP : ℝ} @@ -181,7 +291,14 @@ theorem restricted_lines_consistency_bound :                (((points.Q p2.side sample.1.2 sample.2.2).postprocess fun ab =>                  (some ab.1, some ab.2)).effect answer))              S.psiHat ≤ C * (P.m : ℝ) ^ 2 * δP := by -  sorry +  refine ⟨4, by norm_num, ?_⟩ +  intro P ε δQ δP S points lines p1 p2 hopp kindX kindZ i j +  exact consistencyDefect_restricted_prod_le S p1 p2 hopp +    (fun sample => (lines.T p1.side sample.1.1 sample.2.1).postprocess fun fs => +      (evalOpt sample.1.1 sample.1.2 fs.1, evalOpt sample.2.1 sample.2.2 fs.2)) +    (fun sample => (points.Q p2.side sample.1.2 sample.2.2).postprocess fun ab => +      (some ab.1, some ab.2)) +    (lines.consistent p1 p2 hopp) kindX kindZ i j    /-! ## The sub-line distribution -/   @@ -199,11 +316,35 @@ place of the seed-indexed line-point distribution over `F_q^(2m+2)` of the  source statement, so the statement carries no divisibility hypothesis and its  transport to the source carrier remains open.  Its `source_mixture` field  asserts only the separate X and Z marginal mixtures, not a stronger joint -conditional law.  The proof is tracked by issue #18.  Discharge: formalize the -two sampling cases of the cited construction for `DirectLineDesc`. -/ +conditional law. + +The witness is the sub-line law `subLineDist` of the sampling procedure.  Its +pointwise fields follow from `subLineTripleOf_incidence`, +`subLineTripleOf_compatibility`, and `subLineTripleOf_axis_closure`, after +recovering the auxiliary sample with `exists_raw_of_mem_subLineDist_support`. +Its extended-line marginal is `subLineDist_map_fst`, and its two projected +point marginals are the separate mixtures of `subLineDist_source_mixture`. -/  theorem exists_subLineWitness (P : AdmissibleParams) :      Nonempty (SubLineWitness P) := by -  sorry +  refine ⟨{ D := subLineDist P +            isProbability := subLineDist_isProbability P +            extended_marginal := subLineDist_map_fst P +            incidence := ?_ +            compatibility := ?_ +            source_mixture := subLineDist_source_mixture P +            axis_closure := ?_ }⟩ +  · intro sample hsample u hu +    obtain ⟨kind, k, w, hx, hz, rfl⟩ := +      exists_raw_of_mem_subLineDist_support P hsample +    exact subLineTripleOf_incidence P kind k w hx hz hu +  · intro sample hsample +    obtain ⟨kind, k, w, hx, hz, rfl⟩ := +      exists_raw_of_mem_subLineDist_support P hsample +    exact subLineTripleOf_compatibility P kind k w hx hz +  · intro sample hsample haxis +    obtain ⟨kind, k, w, hx, hz, rfl⟩ := +      exists_raw_of_mem_subLineDist_support P hsample +    exact subLineTripleOf_axis_closure P kind k w haxis    end   diff --git a/MIPStarRE/QPBT/Combining/Lines/CombinedMeasurement.lean b/MIPStarRE/QPBT/Combining/Lines/CombinedMeasurement.lean new file mode 100644 index 00000000..c60d57ff --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/CombinedMeasurement.lean @@ -0,0 +1,94 @@ +import MIPStarRE.QPBT.Combining.Witnesses +import MIPStarRE.QPBT.Games.Sandwich + +/-! +# Combined X/Z line measurement + +This module constructs the X-Z-X sandwich POVM used to combine one X-line +measurement with one Z-line measurement.  It also records the orientation of +the sandwich as a one-sided pasted measurement and the two axis-degree support +properties. + +## References + +The construction is the paired-line measurement in `lem:qld-xz-lines`, with +source `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:942-949`. +-/ + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT MIPStarRE.Quantum + +noncomputable section + +/-- The paired-line POVM in the proof of `lem:qld-xz-lines`, paper +`14_analysis_of_the_pauli_basis_test.tex:942-949`. The X effect is the outer +projector. This construction does not assert consistency with a point witness. -/ +def ProjectiveSetting.combinedLineMeasurement {P : AdmissibleParams} {ε : ℝ} +    (S : ProjectiveSetting P ε) (side : PlayerSide) +    (lineX lineZ : LineDesc P.toLdParams) : +    Quantum.Measurement (DegPoly P.toLdParams (P.m * P.d) × +      DegPoly P.toLdParams (P.m * P.d)) (S.ExpandedLocalSpace side) := +  Measurement.ofSumEqOne +    (fun fs => (S.lineMeasExp side .X lineX).effect fs.1 * +      (S.lineMeasExp side .Z lineZ).effect fs.2 * +      (S.lineMeasExp side .X lineX).effect fs.1) +    (fun fs => (pastedMeasurement_isMeasurement +      (S.lineMeasExp side .Z lineZ) (S.lineMeasExp side .X lineX) +      (S.lineMeasExp_isProjective side .X lineX)).1 (fs.2, fs.1)) +    (by +      classical +      have hsum := (pastedMeasurement_isMeasurement +        (S.lineMeasExp side .Z lineZ) (S.lineMeasExp side .X lineX) +        (S.lineMeasExp_isProjective side .X lineX)).2 +      simp only [pastedMeasurement, Fintype.sum_prod_type] at hsum ⊢ +      rw [Finset.sum_comm] +      exact hsum) + +/-- The effects of the paired-line POVM are the source's X-Z-X sandwiches. -/ +@[simp] theorem ProjectiveSetting.combinedLineMeasurement_effect +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) (side : PlayerSide) +    (lineX lineZ : LineDesc P.toLdParams) +    (fX fZ : DegPoly P.toLdParams (P.m * P.d)) : +    (S.combinedLineMeasurement side lineX lineZ).effect (fX, fZ) = +      (S.lineMeasExp side .X lineX).effect fX * +        (S.lineMeasExp side .Z lineZ).effect fZ * +        (S.lineMeasExp side .X lineX).effect fX := rfl + +/-- The constructed X-outer sandwich is the one-sided pasting output with +`G1 = Z`, `G2 = X`, and the polynomial answers exchanged. This identity fixes +the orientation in paper `14_analysis_of_the_pauli_basis_test.tex:943-961`; +it asserts no unproved consistency relation. -/ +theorem ProjectiveSetting.combinedLineMeasurement_effect_eq_pastedMeasurement +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) (side : PlayerSide) +    (lineX lineZ : LineDesc P.toLdParams) +    (fX fZ : DegPoly P.toLdParams (P.m * P.d)) : +    (S.combinedLineMeasurement side lineX lineZ).effect (fX, fZ) = +      pastedMeasurement (S.lineMeasExp side .Z lineZ).effect +        (S.lineMeasExp side .X lineX).effect fZ fX := rfl + +/-- The X-axis degree bound for the constructed POVM, from the support +argument at paper `14_analysis_of_the_pauli_basis_test.tex:949`. -/ +theorem ProjectiveSetting.combinedLineMeasurement_axis_degree_X +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) (side : PlayerSide) +    (lineX lineZ : LineDesc P.toLdParams) +    (fX fZ : DegPoly P.toLdParams (P.m * P.d)) +    (haxis : lineX.kind = .axis) (hf : ¬ fX.FitsDegree P.d) : +    (S.combinedLineMeasurement side lineX lineZ).effect (fX, fZ) = 0 := by +  simp only [S.combinedLineMeasurement_effect, S.lineMeasExp_effect, +    S.expLineOp_zero_of_not_deg_d side .X lineX haxis fX hf, zero_mul] + +/-- The Z-axis degree bound for the constructed POVM, from the support +argument at paper `14_analysis_of_the_pauli_basis_test.tex:949`. -/ +theorem ProjectiveSetting.combinedLineMeasurement_axis_degree_Z +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) (side : PlayerSide) +    (lineX lineZ : LineDesc P.toLdParams) +    (fX fZ : DegPoly P.toLdParams (P.m * P.d)) +    (haxis : lineZ.kind = .axis) (hf : ¬ fZ.FitsDegree P.d) : +    (S.combinedLineMeasurement side lineX lineZ).effect (fX, fZ) = 0 := by +  simp only [S.combinedLineMeasurement_effect, S.lineMeasExp_effect, +    S.expLineOp_zero_of_not_deg_d side .Z lineZ haxis fZ hf, mul_zero, zero_mul] + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean b/MIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean new file mode 100644 index 00000000..81c4a4d7 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean @@ -0,0 +1,266 @@ +import MIPStarRE.QPBT.Combining.Witnesses + +/-! +# Positivity of the consistency defect on opposite placements + +The error-inflation estimates for restricted line distributions apply to +nonnegative averages.  This module supplies the missing nonnegativity: the +integrand of `consistencyDefect` for two complete measurements placed on +opposite registers is a state quadratic form of a positive operator.  Indeed, +after separating the two placements along the corresponding tensor +bipartition, the off-diagonal sum is +`∑_a (place p₁ E_a) (place p₂ (∑_{b ≠ a} F_b))`, a sum of products of +positive operators supported on complementary registers. + +## References + +The consistency defect is blueprint `def:consistency`, paper +`references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:232-248`.  The +placements and their bipartitions are blueprint `def:expanded-state`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:420-450`.  The +nonnegativity is the hypothesis of items 1 and 2 of +blueprint `lem:restricted-line-mixture-bounds`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1058`. +-/ + +open scoped BigOperators Matrix MatrixOrder ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum + +noncomputable section + +/-- The state quadratic form of the zero operator vanishes. -/ +private theorem stateQForm_zero_local {ι : Type*} [Fintype ι] [DecidableEq ι] +    (ψ : EuclideanSpace ℂ ι) : +    DistanceCalculus.stateQForm ψ (0 : Op ι) = 0 := by +  simp [DistanceCalculus.stateQForm, applyOperatorToState] + +/-- Reindexing an operator along an equivalence preserves positivity. +Formalization-only auxiliary for the placement bipartitions of blueprint +`def:expanded-state`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:420-450`. -/ +theorem reindexOp_nonneg {ι κ : Type*} [Finite ι] [Finite κ] +    (e : ι ≃ κ) {M : Op κ} (hM : 0 ≤ M) : +    0 ≤ reindexOp e M := by +  letI := Fintype.ofFinite ι +  letI := Fintype.ofFinite κ +  rw [Matrix.nonneg_iff_posSemidef] at hM ⊢ +  have hsub := hM.submatrix (e : ι → κ) +  simpa [reindexOp, Matrix.reindex_apply] using hsub + +namespace ProjectiveSetting + +variable {P : AdmissibleParams} {ε : ℝ} + +/-- A register placement respects finite sums of operators. -/ +private theorem place_finset_sum_local (S : ProjectiveSetting P ε) +    (p : Placement) {γ : Type*} (s : Finset γ) +    (O : γ → Op (S.ExpandedLocalSpace p.side)) : +    S.place p (∑ g ∈ s, O g) = ∑ g ∈ s, S.place p (O g) := by +  ext i j +  cases p <;> simp only [place, Matrix.sum_apply, Finset.sum_mul, Finset.mul_sum] + +/-- A register placement maps the zero operator to zero. -/ +private theorem place_zero_local (S : ProjectiveSetting P ε) (p : Placement) : +    S.place p (0 : Op (S.ExpandedLocalSpace p.side)) = 0 := by +  ext i j +  cases p <;> simp [place] + +set_option synthInstance.maxSize 400 in +/-- Operators placed on `AA'` and `BA''` commute. -/ +private theorem place_AA'_mul_place_BA''_comm_local +    (S : ProjectiveSetting P ε) +    (X : Op (S.ExpandedLocalSpace .alice)) +    (Y : Op (S.ExpandedLocalSpace .bob)) : +    S.place .AA' X * S.place .BA'' Y = S.place .BA'' Y * S.place .AA' X := by +  have key : ∀ (X' : Op (S.toStrategy.ιA × PauliRegister P)) +      (Y' : Op (S.toStrategy.ιB × PauliRegister P)), +      S.place .AA' X' * S.place .BA'' Y' = +        S.place .BA'' Y' * S.place .AA' X' := by +    intro X' Y' +    rw [← reindexOp_aaBaBipartition_left S X', +      ← reindexOp_aaBaBipartition_right S Y', +      ← WinImplications.reindexOp_mul, ← WinImplications.reindexOp_mul] +    congr 1 +    rw [heteroKron_mul, heteroKron_mul, Matrix.mul_one, Matrix.one_mul, +      Matrix.mul_one, Matrix.one_mul] +  exact key X Y + +set_option synthInstance.maxSize 400 in +/-- Operators placed on `AB''` and `BB'` commute. -/ +private theorem place_AB''_mul_place_BB'_comm_local +    (S : ProjectiveSetting P ε) +    (X : Op (S.ExpandedLocalSpace .alice)) +    (Y : Op (S.ExpandedLocalSpace .bob)) : +    S.place .AB'' X * S.place .BB' Y = S.place .BB' Y * S.place .AB'' X := by +  have key : ∀ (X' : Op (S.toStrategy.ιA × PauliRegister P)) +      (Y' : Op (S.toStrategy.ιB × PauliRegister P)), +      S.place .AB'' X' * S.place .BB' Y' = +        S.place .BB' Y' * S.place .AB'' X' := by +    intro X' Y' +    rw [← reindexOp_abBbBipartition_left S X', +      ← reindexOp_abBbBipartition_right S Y', +      ← WinImplications.reindexOp_mul, ← WinImplications.reindexOp_mul] +    congr 1 +    rw [heteroKron_mul, heteroKron_mul, Matrix.mul_one, Matrix.one_mul, +      Matrix.mul_one, Matrix.one_mul] +  exact key X Y + +set_option synthInstance.maxSize 400 in +/-- Positive operators placed on `AA'` and on `BA''` have a positive product. +Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:420-450`, +blueprint `def:expanded-state`. -/ +theorem place_AA'_mul_place_BA''_nonneg (S : ProjectiveSetting P ε) +    {X : Op (S.ExpandedLocalSpace .alice)} {Y : Op (S.ExpandedLocalSpace .bob)} +    (hX : 0 ≤ X) (hY : 0 ≤ Y) : +    0 ≤ S.place .AA' X * S.place .BA'' Y := by +  have key : ∀ (X' : Op (S.toStrategy.ιA × PauliRegister P)) +      (Y' : Op (S.toStrategy.ιB × PauliRegister P)), +      0 ≤ X' → 0 ≤ Y' → 0 ≤ S.place .AA' X' * S.place .BA'' Y' := by +    intro X' Y' hX' hY' +    have hprod : S.place .AA' X' * S.place .BA'' Y' = +        reindexOp (aaBaBipartition P S.toStrategy.ιA S.toStrategy.ιB) +          (heteroKron X' (heteroKron Y' +            (1 : Op (PauliRegister P × PauliRegister P)))) := by +      rw [← reindexOp_aaBaBipartition_left S X', +        ← reindexOp_aaBaBipartition_right S Y', +        ← WinImplications.reindexOp_mul, heteroKron_mul, Matrix.mul_one, +        Matrix.one_mul] +    rw [hprod] +    refine reindexOp_nonneg _ ?_ +    exact kronecker_nonneg hX' +      (kronecker_nonneg hY' Matrix.PosSemidef.one.nonneg) +  exact key X Y hX hY + +set_option synthInstance.maxSize 400 in +/-- Positive operators placed on `AB''` and on `BB'` have a positive product. +Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:420-450`, +blueprint `def:expanded-state`. -/ +theorem place_AB''_mul_place_BB'_nonneg (S : ProjectiveSetting P ε) +    {X : Op (S.ExpandedLocalSpace .alice)} {Y : Op (S.ExpandedLocalSpace .bob)} +    (hX : 0 ≤ X) (hY : 0 ≤ Y) : +    0 ≤ S.place .AB'' X * S.place .BB' Y := by +  have key : ∀ (X' : Op (S.toStrategy.ιA × PauliRegister P)) +      (Y' : Op (S.toStrategy.ιB × PauliRegister P)), +      0 ≤ X' → 0 ≤ Y' → 0 ≤ S.place .AB'' X' * S.place .BB' Y' := by +    intro X' Y' hX' hY' +    have hprod : S.place .AB'' X' * S.place .BB' Y' = +        reindexOp (abBbBipartition P S.toStrategy.ιA S.toStrategy.ιB) +          (heteroKron X' (heteroKron Y' +            (1 : Op (PauliRegister P × PauliRegister P)))) := by +      rw [← reindexOp_abBbBipartition_left S X', +        ← reindexOp_abBbBipartition_right S Y', +        ← WinImplications.reindexOp_mul, heteroKron_mul, Matrix.mul_one, +        Matrix.one_mul] +    rw [hprod] +    refine reindexOp_nonneg _ ?_ +    exact kronecker_nonneg hX' +      (kronecker_nonneg hY' Matrix.PosSemidef.one.nonneg) +  exact key X Y hX hY + +/-- Positive operators placed on a directed opposite pair of registers have a +positive product.  Paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:420-450`, +blueprint `def:expanded-state`. -/ +theorem place_mul_place_nonneg (S : ProjectiveSetting P ε) +    (p₁ p₂ : Placement) (hopp : p₁.IsOpposite p₂) +    {X : Op (S.ExpandedLocalSpace p₁.side)} +    {Y : Op (S.ExpandedLocalSpace p₂.side)} +    (hX : 0 ≤ X) (hY : 0 ≤ Y) : +    0 ≤ S.place p₁ X * S.place p₂ Y := by +  cases p₁ <;> cases p₂ <;> simp only [Placement.IsOpposite] at hopp +  · exact place_AA'_mul_place_BA''_nonneg S hX hY +  · rw [← place_AA'_mul_place_BA''_comm_local S Y X] +    exact place_AA'_mul_place_BA''_nonneg S hY hX +  · rw [← place_AB''_mul_place_BB'_comm_local S Y X] +    exact place_AB''_mul_place_BB'_nonneg S hY hX +  · exact place_AB''_mul_place_BB'_nonneg S hX hY + +end ProjectiveSetting + +/-! ## Nonnegativity of the pointwise consistency defect -/ + +/-- The off-diagonal outcome sum of two complete measurements placed on +opposite registers is a positive operator.  Formalization-only auxiliary for +blueprint `def:consistency`, paper +`references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:232-248`. -/ +theorem offDiagonalPlacedProduct_nonneg {P : AdmissibleParams} {ε : ℝ} +    {α : Type*} [Fintype α] [DecidableEq α] (S : ProjectiveSetting P ε) +    (p₁ p₂ : Placement) (hopp : p₁.IsOpposite p₂) +    (M₁ : MIPStarRE.Quantum.Measurement α (S.ExpandedLocalSpace p₁.side)) +    (M₂ : MIPStarRE.Quantum.Measurement α (S.ExpandedLocalSpace p₂.side)) : +    0 ≤ ∑ a : α, ∑ b : α, +      if a = b then 0 +      else S.place p₁ (M₁.effect a) * S.place p₂ (M₂.effect b) := by +  classical +  have hcomplement : ∀ a : α, +      0 ≤ ∑ b : α, if a = b then (0 : Op (S.ExpandedLocalSpace p₂.side)) +        else M₂.effect b := by +    intro a +    refine Finset.sum_nonneg fun b _ => ?_ +    by_cases h : a = b +    · rw [if_pos h] +    · rw [if_neg h] +      exact M₂.pos b +  have hrow : ∀ a : α, +      (∑ b : α, if a = b then (0 : Op (SixReg P S.toStrategy.ιA +          S.toStrategy.ιB)) +        else S.place p₁ (M₁.effect a) * S.place p₂ (M₂.effect b)) = +      S.place p₁ (M₁.effect a) * +        S.place p₂ (∑ b : α, if a = b then 0 else M₂.effect b) := by +    intro a +    rw [ProjectiveSetting.place_finset_sum_local, Finset.mul_sum] +    refine Finset.sum_congr rfl fun b _ => ?_ +    by_cases h : a = b +    · rw [if_pos h, if_pos h, ProjectiveSetting.place_zero_local, mul_zero] +    · rw [if_neg h, if_neg h] +  rw [Finset.sum_congr rfl fun a _ => hrow a] +  refine Finset.sum_nonneg fun a _ => ?_ +  exact ProjectiveSetting.place_mul_place_nonneg S p₁ p₂ hopp (M₁.pos a) +    (hcomplement a) + +/-- The integrand of the consistency defect of two complete measurements placed +on opposite registers is nonnegative.  This is the positivity hypothesis needed +by items 1 and 2 of blueprint `lem:restricted-line-mixture-bounds`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1058`. -/ +theorem consistencyDefect_integrand_nonneg {P : AdmissibleParams} {ε : ℝ} +    {α : Type*} [Fintype α] [DecidableEq α] (S : ProjectiveSetting P ε) +    (p₁ p₂ : Placement) (hopp : p₁.IsOpposite p₂) +    (M₁ : MIPStarRE.Quantum.Measurement α (S.ExpandedLocalSpace p₁.side)) +    (M₂ : MIPStarRE.Quantum.Measurement α (S.ExpandedLocalSpace p₂.side)) : +    0 ≤ ∑ a : α, ∑ b : α, +      if a = b then 0 +      else (inner ℂ S.psiHat +        ((EuclideanSpace.equiv (SixReg P S.toStrategy.ιA S.toStrategy.ιB) +            ℂ).symm +          ((S.place p₁ (M₁.effect a) * S.place p₂ (M₂.effect b)).mulVec +            S.psiHat))).re := by +  classical +  have hform : (∑ a : α, ∑ b : α, +        if a = b then 0 +        else (inner ℂ S.psiHat +          ((EuclideanSpace.equiv (SixReg P S.toStrategy.ιA S.toStrategy.ιB) +              ℂ).symm +            ((S.place p₁ (M₁.effect a) * S.place p₂ (M₂.effect b)).mulVec +              S.psiHat))).re) = +      DistanceCalculus.stateQForm S.psiHat +        (∑ a : α, ∑ b : α, if a = b then 0 +          else S.place p₁ (M₁.effect a) * S.place p₂ (M₂.effect b)) := by +    rw [DistanceCalculus.stateQForm_finset_sum] +    refine Finset.sum_congr rfl fun a _ => ?_ +    rw [DistanceCalculus.stateQForm_finset_sum] +    refine Finset.sum_congr rfl fun b _ => ?_ +    by_cases h : a = b +    · rw [if_pos h, if_pos h, stateQForm_zero_local] +    · rw [if_neg h, if_neg h] +      rfl +  rw [hform] +  exact DistanceCalculus.stateQForm_nonneg S.psiHat +    (offDiagonalPlacedProduct_nonneg S p₁ p₂ hopp M₁ M₂) + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/Marginal.lean b/MIPStarRE/QPBT/Combining/Lines/Marginal.lean new file mode 100644 index 00000000..021381a9 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/Marginal.lean @@ -0,0 +1,36 @@ +import MIPStarRE.QPBT.Combining.Lines.CombinedMeasurement + +/-! +# Marginal of the combined line measurement + +This module records the exact X marginal of the X-Z-X sandwich measurement. + +## References + +The construction is the paired-line measurement in `lem:qld-xz-lines`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:942-963`. +-/ + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT MIPStarRE.Quantum + +noncomputable section + +/-- Formalization-only constructor identity: summing out the Z outcome from +the X-outer sandwich recovers the X line effect exactly. This uses completeness +of the Z measurement and projectivity of the outer X effect, as in the POVM +construction at paper `14_analysis_of_the_pauli_basis_test.tex:942-963`. -/ +theorem ProjectiveSetting.combinedLineMeasurement_sum_Z +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) (side : PlayerSide) +    (lineX lineZ : LineDesc P.toLdParams) +    (fX : DegPoly P.toLdParams (P.m * P.d)) : +    ∑ fZ, (S.combinedLineMeasurement side lineX lineZ).effect (fX, fZ) = +      (S.lineMeasExp side .X lineX).effect fX := by +  simp only [S.combinedLineMeasurement_effect, ← Finset.sum_mul, ← Finset.mul_sum, +    (S.lineMeasExp side .Z lineZ).sum_eq_one, mul_one] +  exact (S.lineMeasExp_isProjective side .X lineX fX).1 + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean b/MIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean new file mode 100644 index 00000000..afea195c --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean @@ -0,0 +1,232 @@ +import MIPStarRE.QPBT.Combining.Lines.RestrictedMixture +import MIPStarRE.QPBT.Combining.Witnesses + +/-! +# Error inflation of restricted line-point averages + +This module records how a nonnegative average over the line-point distribution +transfers to one restricted component.  The line-point law places weight +`1 / 2` on each of its two kinds and, inside each kind, weight `1 / m` on each +coordinate index, so every restricted component carries mixture weight +`1 / (2 m)` and a nonnegative average inflates by at most `2 m`. + +## References + +The estimates are items 1 and 2 of blueprint +`lem:restricted-line-mixture-bounds`, formalizing the unlabelled estimates at +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1058`. +-/ + +open scoped BigOperators + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement + +noncomputable section + +/-! ## Averages of the distribution operations -/ + +/-- Formalization-only auxiliary: an average against a dependent bind is the +iterated average.  Blueprint `lem:restricted-line-mixture-bounds`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1058`. -/ +theorem avgOver_bind {α β : Type*} [DecidableEq β] +    (μ : Distribution α) (ν : α → Distribution β) (f : β → ℝ) : +    avgOver (Distribution.bind μ ν) f = +      avgOver μ (fun a => avgOver (ν a) f) := by +  classical +  unfold avgOver +  have h1 : ∀ b : β, (∑ a ∈ μ.support, μ.weight a * (ν a).weight b) * f b = +      ∑ a ∈ μ.support, μ.weight a * ((ν a).weight b * f b) := by +    intro b +    rw [Finset.sum_mul] +    exact Finset.sum_congr rfl fun a _ => by ring +  change (∑ b ∈ μ.support.biUnion (fun a => (ν a).support), +    (∑ a ∈ μ.support, μ.weight a * (ν a).weight b) * f b) = _ +  rw [Finset.sum_congr rfl fun b _ => h1 b, Finset.sum_comm] +  refine Finset.sum_congr rfl fun a ha => ?_ +  rw [← Finset.mul_sum] +  congr 1 +  refine (Finset.sum_subset ?_ ?_).symm +  · intro b hb +    exact Finset.mem_biUnion.mpr ⟨a, ha, hb⟩ +  · intro b _ hb +    rw [(ν a).outsideSupport b hb, zero_mul] + +/-- Formalization-only auxiliary: an average against a convex mixture is the +convex combination of the two averages.  Blueprint +`lem:restricted-line-mixture-bounds`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1058`. -/ +theorem avgOver_mix {α : Type*} [DecidableEq α] (t : ℝ) (ht0 : 0 ≤ t) +    (ht1 : t ≤ 1) (μ ν : Distribution α) (f : α → ℝ) : +    avgOver (Distribution.mix t ht0 ht1 μ ν) f = +      t * avgOver μ f + (1 - t) * avgOver ν f := by +  classical +  unfold avgOver +  have hsplit : (∑ a ∈ μ.support ∪ ν.support, +        (t * μ.weight a + (1 - t) * ν.weight a) * f a) = +      t * (∑ a ∈ μ.support ∪ ν.support, μ.weight a * f a) + +        (1 - t) * (∑ a ∈ μ.support ∪ ν.support, ν.weight a * f a) := by +    rw [Finset.mul_sum, Finset.mul_sum, ← Finset.sum_add_distrib] +    exact Finset.sum_congr rfl fun a _ => by ring +  have hμ : (∑ a ∈ μ.support ∪ ν.support, μ.weight a * f a) = +      ∑ a ∈ μ.support, μ.weight a * f a := by +    refine (Finset.sum_subset Finset.subset_union_left ?_).symm +    intro a _ ha +    rw [μ.outsideSupport a ha, zero_mul] +  have hν : (∑ a ∈ μ.support ∪ ν.support, ν.weight a * f a) = +      ∑ a ∈ ν.support, ν.weight a * f a := by +    refine (Finset.sum_subset Finset.subset_union_right ?_).symm +    intro a _ ha +    rw [ν.outsideSupport a ha, zero_mul] +  change (∑ a ∈ μ.support ∪ ν.support, +    (t * μ.weight a + (1 - t) * ν.weight a) * f a) = _ +  rw [hsplit, hμ, hν] + +/-- Formalization-only auxiliary: an average against a product law is the +iterated average.  Blueprint `lem:restricted-line-mixture-bounds`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1056-1058`. -/ +theorem avgOver_prod {α β : Type*} [DecidableEq α] [DecidableEq β] +    (μ : Distribution α) (ν : Distribution β) (f : α × β → ℝ) : +    avgOver (Distribution.prod μ ν) f = +      avgOver μ (fun a => avgOver ν (fun b => f (a, b))) := by +  classical +  unfold avgOver +  change (∑ p ∈ μ.support ×ˢ ν.support, μ.weight p.1 * ν.weight p.2 * f p) = _ +  rw [Finset.sum_product] +  refine Finset.sum_congr rfl fun a _ => ?_ +  rw [Finset.mul_sum] +  exact Finset.sum_congr rfl fun b _ => by ring + +/-- Formalization-only auxiliary: one component of a uniform mixture carries at +most the whole nonnegative average, scaled by its mixture weight.  Blueprint +`lem:restricted-line-mixture-bounds`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1056`. -/ +theorem avgOver_bind_uniform_component_le {ι β : Type*} +    [Fintype ι] [DecidableEq ι] [Nonempty ι] [DecidableEq β] +    (ν : ι → Distribution β) (f : β → ℝ) (hf : ∀ b, 0 ≤ f b) (i : ι) : +    1 / (Fintype.card ι : ℝ) * avgOver (ν i) f ≤ +      avgOver (Distribution.bind (uniformDistribution ι) ν) f := by +  classical +  rw [avgOver_bind] +  have hterm : ∀ j ∈ (Finset.univ : Finset ι), +      0 ≤ (uniformDistribution ι).weight j * avgOver (ν j) f := fun j _ => +    mul_nonneg ((uniformDistribution ι).nonnegative j) (avgOver_nonneg _ _ hf) +  have hsingle := Finset.single_le_sum +    (f := fun j => (uniformDistribution ι).weight j * avgOver (ν j) f) +    hterm (Finset.mem_univ i) +  rw [uniformDistribution_weight_apply] at hsingle +  exact hsingle + +/-! ## Inflation of a restricted line-point average -/ + +/-- Restricting a nonnegative line-point average to one kind and one coordinate +index inflates it by at most `2 m`.  This is the pointwise form of item 1 of +blueprint `lem:restricted-line-mixture-bounds`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1056`. -/ +theorem avgOver_restrictedLinePointDist_le {P : AdmissibleParams} +    (f : (LineDesc P.toLdParams × (Fin P.m → PauliScalar P)) → ℝ) +    (hf : ∀ sample, 0 ≤ f sample) (kind : LineKind) (i : Fin P.m) : +    avgOver (restrictedLinePointDist P kind i) f ≤ +      2 * (P.m : ℝ) * avgOver (linePointDist P.toLdParams) f := by +  classical +  haveI : Nonempty (Fin P.m) := +    Fin.pos_iff_nonempty.mp (lt_of_lt_of_le Nat.zero_lt_one P.one_le_m) +  have hm : (0 : ℝ) < (P.m : ℝ) := by +    exact_mod_cast lt_of_lt_of_le Nat.zero_lt_one P.one_le_m +  have hAnonneg : 0 ≤ avgOver (aLinePointDist P.toLdParams) f := +    avgOver_nonneg _ _ hf +  have hDnonneg : 0 ≤ avgOver (dLinePointDist P.toLdParams) f := +    avgOver_nonneg _ _ hf +  have hmixture : avgOver (linePointDist P.toLdParams) f = +      1 / 2 * avgOver (aLinePointDist P.toLdParams) f + +        (1 - 1 / 2) * avgOver (dLinePointDist P.toLdParams) f := +    avgOver_mix _ _ _ _ _ f +  -- Each kind is bounded by twice the full line-point average. +  have hsum : 2 * avgOver (linePointDist P.toLdParams) f = +      avgOver (aLinePointDist P.toLdParams) f + +        avgOver (dLinePointDist P.toLdParams) f := by +    rw [hmixture] +    ring +  have hAle : avgOver (aLinePointDist P.toLdParams) f ≤ +      2 * avgOver (linePointDist P.toLdParams) f := by +    rw [hsum] +    exact le_add_of_nonneg_right hDnonneg +  have hDle : avgOver (dLinePointDist P.toLdParams) f ≤ +      2 * avgOver (linePointDist P.toLdParams) f := by +    rw [hsum] +    exact le_add_of_nonneg_left hAnonneg +  -- The coordinate index contributes a further factor `m`. +  have hcomponent : ∀ (ν : Fin P.m → Distribution (LineDesc P.toLdParams × +      (Fin P.m → PauliScalar P))) (