t hDnonneg +  have hDle : avgOver (dLinePointDist P.toLdParams) f ≤ +      2 * avgOver (linePointDist P.toLdParams) f := by +    rw [hsum] +    exact le_add_of_nonneg_left hAnonneg +  -- The coordinate index contributes a further factor `m`. +  have hcomponent : ∀ (ν : Fin P.m → Distribution (LineDesc P.toLdParams × +      (Fin P.m → PauliScalar P))) (μ : Distribution (LineDesc P.toLdParams × +      (Fin P.m → PauliScalar P))), +      μ = Distribution.bind (uniformDistribution (Fin P.m)) ν → +      avgOver μ f ≤ 2 * avgOver (linePointDist P.toLdParams) f → +      avgOver (ν i) f ≤ 2 * (P.m : ℝ) * avgOver (linePointDist P.toLdParams) f := by +    intro ν μ hbind hle +    have hcomp := avgOver_bind_uniform_component_le ν f hf i +    rw [Fintype.card_fin, ← hbind] at hcomp +    have hstep : avgOver (ν i) f ≤ (P.m : ℝ) * avgOver μ f := by +      rw [div_mul_eq_mul_div, one_mul, div_le_iff₀ hm] at hcomp +      rw [mul_comm] +      exact hcomp +    calc avgOver (ν i) f ≤ (P.m : ℝ) * avgOver μ f := hstep +      _ ≤ (P.m : ℝ) * (2 * avgOver (linePointDist P.toLdParams) f) := by +          exact mul_le_mul_of_nonneg_left hle (le_of_lt hm) +      _ = 2 * (P.m : ℝ) * avgOver (linePointDist P.toLdParams) f := by ring +  cases kind with +  | axis => +      exact hcomponent (restrictedALineDist P.toLdParams) _ +        (aLinePointDist_eq_bind_restricted P.toLdParams) hAle +  | diagonal => +      exact hcomponent (restrictedDLineDist P.toLdParams) _ +        (dLinePointDist_eq_bind_restricted P.toLdParams) hDle + +/-- Restricting a nonnegative average over two independent line-point samples +to one kind and coordinate index in each factor inflates it by at most +`4 m ^ 2`.  This is the pointwise form of item 2 of +blueprint `lem:restricted-line-mixture-bounds`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1056-1058`. -/ +theorem avgOver_prod_restrictedLinePointDist_le {P : AdmissibleParams} +    (f : ((LineDesc P.toLdParams × (Fin P.m → PauliScalar P)) × +